class Solution:
    def maximizeSumOfRatings(self, units: List[List[int]]) -> int:
        m = len(units)
        ac = []
        total = 0
        for row in units:
            a = b = float('inf')
            for v in row:
                if v < a:
                    b, a = a, v
                elif v < b:
                    b = v
            c = a if len(row) == 1 else b
            ac.append((a, c))
            total += c
        d = min(range(m), key=lambda i: ac[i][0])
        best = ac[d][0] + total - ac[d][1]
        if m >= 2:
            cmin = min(ac[i][1] for i in range(m) if i != d)
            bd = ac[d][1] if len(units[d]) == 1 else ac[d][1]
            cand = bd + ac[d][0] + total - ac[d][1] - cmin
            best = max(best, cand)
        return best

