public:
    long long maximizeSumOfRatings(vector<vector<int>>& units) {
        int m = units.size();
        vector<long long> a(m), c(m);
        long long total = 0;
        for (int i = 0; i < m; i++) {
            long long x = LLONG_MAX, y = LLONG_MAX;
            for (int v : units[i]) {
                if (v < x) { y = x; x = v; }
                else if (v < y) y = v;
            }
            a[i] = x;
            c[i] = units[i].size() == 1 ? x : y;
            total += c[i];
        }
        int d = 0;
        for (int i = 1; i < m; i++) if (a[i] < a[d]) d = i;
        long long best = a[d] + total - c[d];
        if (m >= 2) {
            long long cmin = LLONG_MAX;
            for (int j = 0; j < m; j++) if (j != d) cmin = min(cmin, c[j]);
            best = max(best, c[d] + a[d] + total - c[d] - cmin);
        }
        return best;
    }
};

