                    b = v
            cur_a, cur_c = a, (a if len(row) == 1 else b)
            total += cur_c
            if cur_a < ga:
                ga, gi = cur_a, i
            if cur_c < c1:
                c2, c1, ci = c1, cur_c, i
            elif cur_c < c2:
                c2 = cur_c
        best = ga + total - (c1 if gi == ci else 0) if False else None
        cd = cur_c if gi == m - 1 else None
