            long long cc = units[i].size() == 1 ? x : y;
            total += cc;
            lastC.push_back(cc);
            if (x < ga) { ga = x; gi = i; }
            if (cc < c1) { c2 = c1; c1 = cc; ci = i; }
            else if (cc < c2) c2 = cc;
        }
        int m = units.size();
        long long best = ga + total - lastC[gi];
        if (m >= 2) {
            long long cmin = (ci != gi) ? c1 : c2;
            best = max(best, lastC[gi] + ga + total - lastC[gi] - cmin);
        }
        return best;
    }
